onClick:
{{
  (async () => {
    const rawVentil = String(appsmith.store.activeVentil || "").trim();
    if (!rawVentil) {
      showAlert("Fehler: Kein aktives Ventil ausgewählt!", "error");
      return;
    }

    // Formate abfangen und harmonisieren
    const parsedActive = parseFloat(rawVentil.replace(",", "."));
    const storeVentilFormatted = !isNaN(parsedActive) ? parsedActive.toFixed(2) : rawVentil;

    // 1. Zeilen-Index in den Stammdaten suchen
    const stammdatenList = [...(appsmith.store.lokaleStammdaten || Stammdaten.data || [])];

    const foundIndex = stammdatenList.findIndex(r => {
      const vL = String(r.Ventil_Links || "").trim().replace(",", ".");
      const vR = String(r.Ventil_Rechts || "").trim().replace(",", ".");

      const matchL = vL === storeVentilFormatted || (!isNaN(parseFloat(vL)) && parseFloat(vL).toFixed(2) === storeVentilFormatted);
      const matchR = vR === storeVentilFormatted || (!isNaN(parseFloat(vR)) && parseFloat(vR).toFixed(2) === storeVentilFormatted);

      return matchL || matchR;
    });

    if (foundIndex === -1) {
      showAlert("Fehler: Ventil wurde nicht in den Stammdaten gefunden!", "error");
      return;
    }

    // 2. Seite identifizieren (Links oder Rechts)
    const row = { ...stammdatenList[foundIndex] };
    const vL = String(row.Ventil_Links || "").trim().replace(",", ".");
    const isLeft = vL === storeVentilFormatted || (!isNaN(parseFloat(vL)) && parseFloat(vL).toFixed(2) === storeVentilFormatted);

    // 3. Lokalen Stammdaten-Store direkt aktualisieren
    if (isLeft) {
      row.Status_Leer_Links = true;
    } else {
      row.Status_Leer_Rechts = true;
    }
    stammdatenList[foundIndex] = row;

    // 4. Stores setzen & Re-Render auslösen
    await storeValue('lokaleStammdaten', [...stammdatenList]);
    await storeValue('Ventil_Leer_' + storeVentilFormatted, true);
    await storeValue('lastUpdate', Date.now());

    // Modal sofort schließen
    closeModal('Modal_Programm');

    // 5. Im Hintergrund an Google Sheets senden (OHNE Refetch/Reload!)
    try {
      await Stammdaten_Update.run({
        targetIndex: foundIndex,
        neuerStatus: true,
        isLeft: isLeft
      });

    } catch (e) {
      showAlert("Fehler beim Updaten: " + e.message, "error");
    }
  })()
}}
